import numpy as np,json
rng=np.random.default_rng(16);N=100000
q=rng.integers(0,256,(N,8));q[:,7]=q[:,2];rec=rng.integers(0,256,(N,4,8));rec[:,:,7]=rec[:,:,2];raw=rng.random((N,4));raw*=.93/np.maximum(1,raw.sum(1))[:,None];caps=(255-rec)//4;ratios=np.divide(caps,q[:,None,:]*raw[:,:,None],out=np.ones((N,4,8)),where=(q[:,None,:]*raw[:,:,None])>0);lam=np.minimum(1,ratios.min(2));flux=np.floor(q[:,None,:]*raw[:,:,None]*lam[:,:,None]).astype(int);stay=q-flux.sum(1);assert (stay>=0).all();assert (flux<=caps).all();assert np.array_equal(flux[:,:,2],flux[:,:,7]);assert np.array_equal(stay[:,2],stay[:,7]);print(json.dumps({'cases':N,'all8OutflowPositive':True,'all8IncomingQuarterCapsPASS':True,'PB_CAAllocationExact':True,'anyMovingEdgesFraction':float((flux.sum(2)>0).mean()),'warning':'Exact real common fraction; independent floor changes channel ratios. Globalinteger conservation conditional identical endpoint shader evaluation.'},indent=2))
